void vg_model_set_live(uint16_t idx, float value, bool online)
{
    vg_sensor_t * s;

    if(idx >= s_sensor_n) {
        return;
    }

    s = &s_sensors[idx];
    s->online = online;
    if(online) {
        s->value = value;
        s->base_value = value;
        s->age_sec = 1;
        s->quality_pct = 95;
        s->severity = VG_SEV_OK;
        if(s->history_len < VG_HISTORY_LEN) {
            s->history[s->history_len++] = value;
        }
        else {
            memmove(&s->history[0], &s->history[1],
                    (VG_HISTORY_LEN - 1) * sizeof(float));
            s->history[VG_HISTORY_LEN - 1] = value;
        }
    }
    else {
        if(s->age_sec < 100000) {
            s->age_sec++;
        }
        s->quality_pct = 0;
        s->severity = VG_SEV_OFFLINE;
    }
}

