  (void)baud;

  if (devpath == NULL || out == NULL || addr == 0)
    {
      return -EINVAL;
    }

  if (vg_disc_nmbs_open(&s, devpath) != 0)
    {
      return -errno;
    }

  memset(out, 0, sizeof(uint16_t) * qty);
  err = vg_disc_read_holding(&s, addr, reg, qty, out);
  vg_disc_nmbs_close(&s);

