    for line in pathlib.Path(fp).read_text().splitlines():
        m=re.match(r'(Rx|Tx):(\d+)-([0-9:.]+)-([0-9A-Fa-f ]+)', line.strip())
        if not m: continue
        kind, seq, ts, hexpart=m.groups()
        b=bytes(int(x,16) for x in hexpart.split())
        if kind=='Tx':
            tx+=1
            continue
        rx+=1
        if len(b)<8:
            short+=1
            if len(bad_examples)<6: bad_examples.append(('short', b.hex(' ')))
            continue
        # try 8-byte RTU
        pdu, crc = b[:6], b[6:8]
        lo,hi=modbus_crc(pdu)
        extra=b[8:]
        if extra:
            extra_tail+=1
        if crc[0]==lo and crc[1]==hi:
            crc_ok+=1
            if pdu[1]!=3: fc_bad+=1
            if pdu[0]==0: addr0+=1
            if len(ok_examples)<4: ok_examples.append(b.hex(' '))
        else:
            crc_bad+=1
            if len(bad_examples)<8: bad_examples.append(('badcrc', b.hex(' '), f'expect {lo:02X} {hi:02X}'))
        if len(b)>8:
            long+=1
    print(f'Rx={rx} Tx={tx} crc_ok={crc_ok} crc_bad={crc_bad} short(<8)={short} long(>8)={long} extra_tail={extra_tail}')
    print('ok examples', ok_examples)
    print('bad examples', bad_examples)
PY

